CREATE TABLE IF NOT EXISTS mobile_installation (id varchar(255) primary key, secret_hash varchar(64) not null, device_token varchar(512), environment varchar(255), notification_authorization varchar(255), language varchar(255), client_revision bigint not null default 0, row_version bigint not null default 0);
CREATE TABLE IF NOT EXISTS mobile_subscription (id varchar(255) primary key, installation_id varchar(255) not null unique references mobile_installation(id), journey_key varchar(512) not null, watch_id varchar(256) not null, facts text, progress text, display_state text, last_action varchar(255), activity_id varchar(255), activity_token varchar(512), activity_state varchar(255), activity_generation bigint not null default 0, client_revision bigint not null default 0, snapshot_version bigint not null default 0, ends_at bigint not null, active boolean not null, baseline boolean not null, row_version bigint not null default 0);
CREATE TABLE IF NOT EXISTS mobile_flight_watch (id varchar(256) primary key, flight_number varchar(255), flight_date varchar(255), departure_airport varchar(255), arrival_airport varchar(255), due_at bigint not null, lease_until bigint not null default 0, lease_owner varchar(255), failures integer not null default 0, snapshot_version bigint not null default 0, facts text, row_version bigint not null default 0);
CREATE TABLE IF NOT EXISTS mobile_push_event (id varchar(255) primary key, subscription_id varchar(255) not null, snapshot_version bigint not null, event_type varchar(255), created_at bigint not null, unique(subscription_id,snapshot_version,event_type));
CREATE TABLE IF NOT EXISTS mobile_push_delivery (id varchar(255) primary key, event_id varchar(255) not null references mobile_push_event(id), subscription_id varchar(255), channel varchar(255), token varchar(512), environment varchar(255), payload text, final_message boolean not null default false, priority integer not null, expires_at bigint not null, due_at bigint not null, lease_until bigint not null default 0, lease_owner varchar(255), attempts integer not null default 0, status varchar(255), reason varchar(255), row_version bigint not null default 0, unique(event_id,channel));
CREATE INDEX IF NOT EXISTS mobile_watch_due ON mobile_flight_watch(due_at,lease_until);
CREATE INDEX IF NOT EXISTS mobile_delivery_due ON mobile_push_delivery(status,due_at,lease_until);
CREATE INDEX IF NOT EXISTS mobile_subscription_watch ON mobile_subscription(watch_id,active);
CREATE TABLE IF NOT EXISTS mobile_provider_cooldown (id varchar(255) primary key, retry_at bigint not null);
